using OpenRestoApi.Core.Domain;

namespace OpenRestoApi.Core.Application.Legal;

/// <summary>
/// The wording of the four documents. Square brackets mark what only the operator knows. Nothing
/// here may claim a safeguard the product does not have: each security and retention statement
/// below is one the code enforces (hashed passwords, the audit trail, the retention pass).
/// </summary>
internal static class LegalTexts
{
    private const string Platform = "[Dénomination de la société exploitante]";

    private static LegalSection S(string heading, params string[] paragraphs) => new(heading, paragraphs);

    public static LegalDocument Terms { get; } = new(LegalDocumentKeys.Terms,
        "Conditions d’utilisation de l’offre gratuite",
    [
        S("Modèle à faire valider",
            "Ce texte est un modèle de travail. Il doit être relu et validé par un juriste avant d’être proposé à un restaurant réel. Les champs entre crochets sont à compléter par l’exploitant."),
        S("1. Parties et objet",
            $"Les présentes conditions lient {Platform}, société de droit belge dont le siège est situé à [adresse du siège], inscrite à la Banque-Carrefour des Entreprises sous le numéro [numéro d’entreprise] (ci-après « la Plateforme »), et le restaurateur qui accepte l’invitation de la Plateforme pour y inscrire son établissement (ci-après « le Restaurateur »).",
            "Elles régissent l’usage de l’offre gratuite : une page de réservation en ligne, une carte consultable par code QR et un site vitrine pour l’établissement du Restaurateur."),
        S("2. Description du service",
            "La Plateforme met à disposition du Restaurateur, sur une instance unique qu’elle héberge, les outils suivants : gestion des horaires, des salles et des tables ; prise de réservations par les clients du Restaurateur ; envoi d’e-mails de confirmation ; carte numérique accessible par code QR ; site vitrine d’une page.",
            "Le service est fourni tel quel. La Plateforme peut le faire évoluer, y ajouter ou en retirer des fonctions, sans que cela ouvre un droit à indemnité."),
        S("3. Compte et accès",
            "L’accès se fait sur invitation. Le Restaurateur crée son compte à partir du lien reçu, avec une adresse e-mail et un mot de passe qu’il garde secrets. Il répond de ce qui est fait depuis son compte et prévient la Plateforme sans délai en cas d’usage non autorisé.",
            "Le Restaurateur déclare que les informations qu’il fournit (identité de la société, numéro d’entreprise, adresse, coordonnées) sont exactes et à jour, et qu’il est habilité à engager l’établissement."),
        S("4. Gratuité",
            "L’offre est gratuite : la Plateforme ne prélève aucune commission sur les réservations et ne facture pas l’accès au service.",
            "La Plateforme peut proposer un jour des offres payantes. L’offre gratuite ne change alors qu’après un préavis écrit d’au moins soixante jours, et le Restaurateur reste libre de ne pas souscrire et de quitter la Plateforme.",
            "La gratuité n’emporte aucun engagement de niveau de service."),
        S("5. Obligations du Restaurateur",
            "Le Restaurateur publie des informations loyales : horaires, adresse, carte et prix doivent correspondre à la réalité. Il honore les réservations qu’il a confirmées ou prévient ses clients de tout empêchement.",
            "Il est seul responsable de l’exactitude de sa carte, notamment des allergènes et régimes qu’il y déclare (règlement (UE) n° 1169/2011), et des prix, qui s’entendent toutes taxes comprises.",
            "Il ne publie aucun contenu illicite, trompeur, diffamatoire ou qui porte atteinte aux droits d’un tiers, et garantit disposer des droits sur les textes, logos et photos qu’il met en ligne.",
            "Pour les données de ses clients, il est responsable du traitement au sens du règlement (UE) 2016/679 (RGPD) : il les utilise pour gérer les réservations et pas pour autre chose, et il informe ses clients comme la loi l’exige. La Plateforme agit comme sous-traitante, dans les conditions de l’accord de sous-traitance qui fait partie de l’inscription."),
        S("6. Contenus et propriété intellectuelle",
            "Le Restaurateur conserve tous ses droits sur ses contenus. Il accorde à la Plateforme une licence non exclusive, limitée à la durée de l’inscription, pour les héberger, les reproduire et les afficher dans le seul but de fournir le service.",
            "Le logiciel qui sous-tend le service est un logiciel libre régi par sa propre licence. Le nom et les éléments distinctifs de la Plateforme restent sa propriété."),
        S("7. Disponibilité et sauvegardes",
            "La Plateforme met en œuvre des moyens raisonnables pour que le service soit accessible et que les données soient sauvegardées régulièrement, mais ne garantit ni une disponibilité continue ni l’absence de perte. Des interruptions de maintenance sont possibles.",
            "Le Restaurateur garde de son côté de quoi servir ses clients si le service est indisponible (par exemple un téléphone et un carnet)."),
        S("8. Suspension et fin",
            "La Plateforme peut suspendre un établissement, avec effet immédiat et en en indiquant le motif au Restaurateur, en cas de manquement aux présentes conditions, d’atteinte à la sécurité ou aux droits de tiers, ou sur demande d’une autorité. Un établissement suspendu n’est plus visible ni réservable en ligne ; il est réactivé dès que la cause a disparu.",
            "Le Restaurateur peut quitter la Plateforme à tout moment en le demandant par écrit. La Plateforme peut mettre fin à l’offre gratuite moyennant un préavis de soixante jours, sauf manquement grave.",
