    public static LegalDocument Privacy { get; } = new(LegalDocumentKeys.Privacy,
        "Politique de confidentialité",
    [
        S("Modèle à faire valider",
            "Ce texte est un modèle de travail. Il doit être relu et validé par un juriste avant d’être publié. Les champs entre crochets sont à compléter par l’exploitant."),
        S("Qui fait quoi",
            $"Cette politique couvre deux situations. Pour le compte des restaurateurs (partie A), {Platform} (« la Plateforme ») est responsable du traitement. Pour les clients qui réservent une table (partie B), c’est le restaurant qui est responsable du traitement et la Plateforme n’agit que sur ses instructions, comme sous-traitante.",
            "Contact pour toute question sur vos données : [adresse e-mail vie privée]."),
        S("Partie A — Restaurateurs : données traitées",
            "Adresse e-mail et nom d’affichage du compte ; mot de passe, conservé uniquement sous forme d’empreinte et jamais en clair ; date de dernière connexion ; actions effectuées dans l’espace de gestion (journal d’activité, avec l’adresse IP de l’appareil) ; version et date des documents légaux acceptés ; informations de l’établissement (nom, adresse, numéro d’entreprise, téléphone, horaires, carte, logo)."),
        S("Partie A — Finalités et bases légales",
            "Fournir le service et gérer le compte (exécution du contrat) ; sécuriser le service, détecter les abus et pouvoir établir qui a fait quoi (intérêt légitime) ; prouver l’acceptation des conditions (intérêt légitime) ; respecter nos obligations légales, par exemple comptables ou à la demande d’une autorité (obligation légale)."),
        S("Partie A — Durées de conservation",
            "Les données du compte sont conservées pendant la relation, puis supprimées dans les trente jours qui suivent sa fin. Le journal d’activité est conservé 365 jours. Le journal d’acceptation des documents légaux est conservé pendant la relation et [cinq] ans après sa fin, pour pouvoir prouver le consentement."),
        S("Partie B — Clients des restaurants : données traitées",
            "Lorsque vous réservez : votre nom, votre adresse e-mail, le nombre de couverts, la date et l’heure, vos demandes particulières, la langue de l’interface. Si vous activez les rappels, l’adresse technique de votre appareil ou de votre navigateur pour recevoir la notification.",
            "Ces données servent à gérer votre réservation, à vous envoyer sa confirmation et, si vous le demandez, un rappel. Le restaurant ne les utilise pas pour de la prospection sans votre accord."),
        S("Partie B — Durée de conservation",
            "Votre nom, votre adresse e-mail et vos demandes particulières sont conservés par défaut 12 mois après la date de la réservation. Passé ce délai, ils sont effacés automatiquement : la réservation reste dans les statistiques du restaurant (date, nombre de couverts, table) mais ne permet plus de vous identifier. Le restaurant peut choisir une durée plus courte ou plus longue, entre 1 et 60 mois.",
            "L’adresse technique d’un rappel est supprimée dès que la réservation a eu lieu ou a été annulée."),
        S("Partie B — Vos droits",
            "Vous pouvez demander au restaurant l’accès à vos données, leur rectification, leur effacement, la limitation du traitement, leur portabilité, et vous opposer au traitement. Adressez-vous d’abord au restaurant, qui en est responsable ; la Plateforme l’aide à répondre. Vous pouvez annuler votre réservation vous-même avec le lien de votre e-mail de confirmation."),
        S("Destinataires et transferts",
            "Les données sont hébergées chez [hébergeur], dans [pays]. Les e-mails passent par le serveur de messagerie configuré par la Plateforme. Aucun outil de mesure d’audience ni service publicitaire tiers n’est chargé, et aucune donnée n’est transférée hors de l’Espace économique européen."),
        S("Cookies et stockage local",
            "Le service dépose uniquement ce qui lui est nécessaire : un cookie de session pour les comptes de restaurateurs, un cookie chiffré qui garde en mémoire sur votre appareil les références de vos réservations récentes pendant 90 jours, et dans le navigateur vos préférences d’affichage (langue, thème). Aucun cookie publicitaire ou de mesure : il n’y a donc pas de bandeau à valider."),
        S("Sécurité",
            "Les accès sont protégés par mot de passe et par des droits distincts selon le rôle ; un restaurateur n’accède qu’à son établissement ; la Plateforme ne lit pas les données des clients d’un restaurant sans motif consigné ; les sauvegardes sont régulières."),
        S("Réclamation",
            "Si vous estimez que vos droits ne sont pas respectés, vous pouvez introduire une réclamation auprès de l’Autorité de protection des données (autoriteprotectiondonees.be)."),
    ]);

    public static LegalDocument Dpa { get; } = new(LegalDocumentKeys.Dpa,
